  str_n32_multiline_dialogue_bigplace_6 = "Kartima Mansion",
  str_n32_multiline_dialogue_bigplace_7 = "Center Square",
  str_n32_multiline_dialogue_bigplace_8 = "Kartima Mansion",
  str_n32_multiline_dialogue_bigplace_9 = "Uptown Streets",
  str_n32_multiline_dialogue_smallplace_1 = "Outside the Hall",
  str_n32_multiline_dialogue_smallplace_2 = "Garden",
  str_n32_multiline_dialogue_smallplace_3 = "Peripheral Pathway",
  str_n32_multiline_dialogue_smallplace_4 = "Peripheral Pathway",
  str_n32_multiline_dialogue_smallplace_5 = "Somewhere",
  str_n32_multiline_dialogue_smallplace_6 = "The Tower",
  str_n32_multiline_dialogue_smallplace_7 = "Entrance",
  str_n32_multiline_dialogue_smallplace_8 = "The Tower",
  str_n32_multiline_dialogue_smallplace_9 = "Near the Kartima Mansion",
  str_n32_multiline_main_intro_title = "<color=#68251b><size=55>The Divergence Gameplay Info</size></color>",
  str_n32_multiline_main_intro_head_1 = "<color=#623d33><size=34>Enter the world of the Crystal of Eternal Memory</size></color>",
  str_n32_multiline_main_intro_body_1 = "<color=#ac7655><size=28>With Jakine's help, you can go back in time and space to explore the old Lumopolis. With each attempt, you'll get closer and closer to the truth.</size></color>",
  str_n32_multiline_main_intro_head_2 = "<color=#623d33><size=34>Don't miss out on the encounters along the way</size></color>",
  str_n32_multiline_main_intro_body_2 = "<color=#ac7655><size=28>During your tense journeys, you will experience tough battles and meet different people. When you listen to their conversations, you may be able to find out past events that very few people know about and make some unexpected gains.</size></color>",
  str_n32_multiline_main_intro_head_3 = "<color=#623d33><size=34>Past Events Collection</size></color>",
  str_n32_multiline_main_intro_body_3 = "<color=#ac7655><size=28>The past events you collect during your journey will be sorted in Dossiers, where you can browse or view them at any time to find clues of other past events that you are missing.</size></color>",
  str_n32_multiline_map_intro_title = "<color=#68251b><size=55>The Divergence Gameplay Info</size></color>",
  str_n32_multiline_map_intro_head_1 = "<color=#623d33><size=34>The End of Time Travel</size></color>",
  str_n32_multiline_map_intro_body_1 = "<color=#ac7655><size=28>Although you'll travel to Lumopolis each time, you'll have different battles and encounters in each new journey, so please take each battle seriously and cherish every encounter.</size></color>",
  str_n32_multiline_map_intro_head_2 = "<color=#623d33><size=34>Journey Encounters</size></color>",
  str_n32_multiline_map_intro_body_2 = "<color=#ac7655><size=28>Cherish each encounter on your journey to record a past event that few know about. Past events will be collected in Dossiers, and you can claim a reward after collecting all past events.</size></color>"
}
return config
